export function readiness(b: ReadinessInput): Readiness {
  const facts = (b.meta as { facts?: unknown } | null)?.facts;
  if (!facts || typeof facts !== 'object') return { status: 'unknown', findings: [], passed: [], checked: 0 };
  const r = new Runner();
  const d = (facts as { desktop?: DesktopFacts | null }).desktop;
  if (b.platform === 'MACOS' || b.platform === 'WINDOWS') {
    if (d) desktop(r, d);
    return r.result();
  }
  if (b.platform === 'IOS') ios(r, b, facts as IosFacts);
  else android(r, b, facts as AndroidFacts);
  const x = (facts as { expo?: ExpoFacts | null }).expo;
  if (x) expo(r, b, x);
  const fl = (facts as { flutter?: FlutterFacts | null }).flutter;
  if (fl) flutter(r, b, fl);
  return r.result();
}

class Runner {
  findings: Finding[] = [];
  passed: string[] = [];
  checked = 0;
  /** Records a check; `fail` is the finding when it fails, `name` what passed otherwise. */
  check(name: string, fail: Finding | null) {
    this.checked++;
    if (fail) this.findings.push(fail);
    else this.passed.push(name);
  }
  result(): Readiness {
    const order: Record<Level, number> = { blocker: 0, warning: 1, info: 2 };
    this.findings.sort((a, b) => order[a.level] - order[b.level]);
    const status = this.findings.some((f) => f.level === 'blocker' && f.area !== 'install')
      ? 'blocked'
      : this.findings.some((f) => f.level !== 'info')
        ? 'review'
        : 'ready';
    return { status, findings: this.findings, passed: this.passed, checked: this.checked };
  }
}

const f = (id: string, level: Level, area: Area, title: string, detail: string, fix: string): Finding => ({ id, level, area, title, detail, fix });

// ---------------------------------------------------------------- desktop (rival 13 item 6)

/** Signing lines of a desktop build: what Gatekeeper or SmartScreen will say when a tester opens the file. */
function desktop(r: Runner, d: DesktopFacts) {
  if (d.os === 'macos') {
    const what = d.kind === 'dmg' ? 'disk image' : d.kind === 'pkg' ? 'installer package' : 'app';
    r.check('Signed with a Developer ID certificate',
      d.signature === 'unsigned' && d.kind === 'dmg'
        ? f('mac-dmg-unsigned', 'info', 'install', 'The disk image itself is not signed',
            'That is common and fine when the app inside is signed with Developer ID and notarized. The app inside a disk image is not read here.',
            'To have the disk image checked too, sign it with codesign and a Developer ID Application certificate, notarize and staple it.')
        : d.signature === 'unsigned'
        ? f('mac-unsigned', 'warning', 'install', `The ${what} is not signed`,
            'macOS blocks unsigned downloads by default. Testers have to open System Settings, Privacy and Security, and allow the app by hand.',
            d.kind === 'pkg' ? 'Sign the package with productsign and a Developer ID Installer certificate, then upload it again.' : 'Sign it with codesign and a Developer ID Application certificate (Xcode: Product, Archive, Distribute App, Direct Distribution), then upload it again.')
        : d.signature === 'adhoc'
          ? f('mac-adhoc', 'warning', 'install', `The ${what} is ad hoc signed`,
              'An ad hoc signature has no certificate behind it, so Gatekeeper treats the download like an unsigned one on other Macs.',
              'Sign it with a Developer ID Application certificate instead of the ad hoc identity (codesign --sign "-"), then upload it again.')
          : d.signature === 'apple'
            ? f('mac-not-devid', 'warning', 'install', 'Signed with a development or App Store certificate',
                `${d.signer ?? 'The certificate'} is not a Developer ID certificate, so macOS will not open the download on Macs outside your team without a manual step.`,
                'Export with Direct Distribution (Developer ID) in Xcode, or sign with a Developer ID Application certificate.')
            : null);
    if (d.notarized !== null && d.signature !== 'unsigned') {
      r.check('Notarization ticket stapled',
        d.notarized ? null
          : f('mac-not-notarized', 'warning', 'install', 'No notarization ticket in the file',
              'Without a stapled ticket macOS checks with Apple when the file is opened, and blocks it if the app was never notarized.',
              'Notarize with xcrun notarytool submit --wait, then run xcrun stapler staple on the file and upload it again.'));
    }
    return;
  }
  r.check('Signed package',
    d.signature === 'unsigned'
      ? f('win-unsigned', 'warning', 'install', d.kind === 'msi' ? 'The installer is not signed' : 'The package is not signed',
          d.kind === 'msi'
            ? 'Windows SmartScreen warns about unsigned installers, and testers have to choose More info, Run anyway.'
            : 'Windows does not install an unsigned MSIX or APPX package unless the tester turns on developer mode.',
          d.kind === 'msi' ? 'Sign it with signtool and a code signing certificate, then upload it again.' : 'Sign it with signtool and a certificate whose subject matches the Publisher in the manifest, then upload it again.')
      : null);
}

// ---------------------------------------------------------------- iOS

/** "1620" -> "16.2", "2611" -> "26.1.1". */
export function xcodeVersion(code: string | null): string | null {
  if (!code || !/^\d{4}$/.test(code)) return null;
  const major = Number(code.slice(0, 2));
  const minor = Number(code[2]);
  const patch = Number(code[3]);
  return patch ? `${major}.${minor}.${patch}` : `${major}.${minor}`;
}

function ios(r: Runner, b: ReadinessInput, x: IosFacts) {
  const meta = (b.meta ?? {}) as { deviceFamily?: string[]; profileExpiresAt?: string | null; distribution?: string; minimumOsVersion?: string | null };
  const sdk = /(\d+)(?:\.(\d+))?$/.exec(x.sdkName ?? '');
  const sdkMajor = sdk ? Number(sdk[1]) : null;
  const xcode = xcodeVersion(x.xcode);

  r.check(
    'Built with the iOS 26 SDK',
    sdkMajor === null
      ? f('ios.sdk.unknown', 'warning', 'appStore', 'No Xcode build information',
          'Info.plist has no DTSDKName or DTXcode. The app was likely re-signed or built outside Xcode, and App Store Connect will not accept it as is.',
          'Archive the app in Xcode 26 or later and export it from the Organizer.')
      : sdkMajor < MIN_IOS_SDK
        ? f('ios.sdk.old', 'blocker', 'appStore', `Built with the iOS ${sdk![1]}${sdk![2] ? `.${sdk![2]}` : ''} SDK${xcode ? ` (Xcode ${xcode})` : ''}`,
            'Since April 28, 2026 App Store Connect only accepts builds made with Xcode 26 or later and the iOS 26 SDK. Your minimum iOS version can stay lower.',
            'Install Xcode 26, open the project, fix any new build warnings, then archive and upload again.')
        : null,
  );

  const minOs = /^(\d+)(?:\.\d+)*$/.exec(meta.minimumOsVersion ?? '');
  if (minOs) {
    r.check(
      `Minimum iOS ${MIN_IOS_TARGET} or later`,
      Number(minOs[1]) < MIN_IOS_TARGET
        ? f('ios.minos.old', 'blocker', 'appStore', `Minimum iOS ${meta.minimumOsVersion}`,
            `Since September 9, 2026 App Store Connect only accepts iOS and iPadOS apps that target iOS ${MIN_IOS_TARGET} or later.`,
            `Set the iOS Deployment Target to ${MIN_IOS_TARGET}.0 or later in Xcode (and in your Podfile, Flutter or React Native settings), then archive and upload again.`)
        : null,
    );
  }

  r.check(
    'Privacy manifest in the app',
    x.privacyManifest
      ? null
      : f('ios.privacy.app', 'warning', 'appStore', 'No privacy manifest in the app',
          'There is no PrivacyInfo.xcprivacy in the app bundle. Almost every app uses at least one "required reason" API (for example UserDefaults or file timestamps), and App Store Connect rejects uploads that use them without declaring a reason (ITMS-91053).',
          'In Xcode choose File > New > File > App Privacy, add it to the app target, and list the required reason APIs and collected data types your app uses.'),
  );

  const sdkMissing = x.frameworks.filter((fw) => !fw.privacyManifest && PRIVACY_SDKS.has(fw.name.toLowerCase())).map((fw) => fw.name);
  r.check(
    'Privacy manifests in third party SDKs',
    sdkMissing.length
      ? f('ios.privacy.sdk', 'warning', 'appStore', `${sdkMissing.length} SDK${sdkMissing.length > 1 ? 's' : ''} without a privacy manifest`,
          `${sdkMissing.join(', ')} ${sdkMissing.length > 1 ? 'are' : 'is'} on Apple's list of SDKs that must ship a privacy manifest and signature. New apps, and updates that add one of them, are rejected without it (ITMS-91061).`,
          'Update these SDKs to their current versions (CocoaPods, Swift Package Manager or pub), which include the manifest, then build again.')
      : null,
  );

  r.check(
    'Permission texts filled in',
    x.emptyUsageKeys.length
      ? f('ios.usage.empty', 'blocker', 'appStore', 'Empty permission text',
          `${x.emptyUsageKeys.join(', ')} ${x.emptyUsageKeys.length > 1 ? 'have' : 'has'} no text. iOS shows this text when it asks the user, and App Review rejects empty or vague reasons (guideline 5.1.1).`,
          'Write one clear sentence per key in Info.plist that says what the app does with the data, for example "Used to scan receipts with the camera".')
      : null,
  );

  r.check(
    'Launch screen storyboard',
    x.launchStoryboard
      ? null
      : f('ios.launch', 'blocker', 'appStore', 'No launch screen storyboard',
          'Info.plist has no UILaunchStoryboardName or UILaunchScreen. App Store Connect requires a launch screen made with a storyboard or the UILaunchScreen key.',
          'Add a LaunchScreen.storyboard to the app target, or a UILaunchScreen dictionary in Info.plist.'),
  );

  r.check(
    'App icon from an asset catalog',
    x.assetCatalogIcon
      ? null
      : f('ios.icon', 'blocker', 'appStore', 'App icon not set from an asset catalog',
          'CFBundleIconName is missing, so App Store Connect cannot find the app icon (ITMS-90713). It also needs a 1024 x 1024 icon without transparency.',
          'Add an AppIcon set to Assets.xcassets, set it as the App Icon in the target settings, and archive again.'),
  );

  const family = meta.deviceFamily ?? [];
  const allOrientations = ['UIInterfaceOrientationPortrait', 'UIInterfaceOrientationPortraitUpsideDown', 'UIInterfaceOrientationLandscapeLeft', 'UIInterfaceOrientationLandscapeRight'];
  if (family.includes('iPad')) {
    const missing = allOrientations.filter((o) => !(x.ipadOrientations ?? []).includes(o));
    r.check(
      'iPad multitasking orientations',
      !x.requiresFullScreen && missing.length
        ? f('ios.ipad.orientation', 'blocker', 'appStore', 'iPad orientations incomplete',
            'The app runs on iPad and supports multitasking, so it must support all four orientations. App Store Connect rejects it otherwise (ITMS-90474).',
            'Turn on all four iPad orientations in the target settings, or set "Requires full screen" if the app cannot rotate.')
        : null,
    );
  }

  const versionOk = (v: string | null) => !!v && /^\d+(\.\d+){0,2}$/.test(v);
  r.check(
    'Version numbers in the right format',
    !versionOk(b.version) || !versionOk(b.versionCode)
      ? f('ios.version', 'blocker', 'appStore', 'Version number in the wrong format',
          `Version "${b.version ?? ''}" and build "${b.versionCode ?? ''}" must each be one to three numbers separated by dots, like 2.4 or 2.4.1 (ITMS-90060).`,
          'Change Version and Build in the target settings to plain numbers, for example 2.4.1 and 57.')
      : null,
  );

  if (x.archs.length) {
    r.check(
      '64-bit binary',
      x.archs.some((a) => a === 'arm64')
        ? null
        : f('ios.arch', 'blocker', 'appStore', 'No 64-bit code',
            `The app binary only contains ${x.archs.join(', ')}. iOS and App Store Connect require arm64.`,
            'Set Architectures to "Standard Architectures" in the build settings and archive again.'),
    );
  }

  r.check(
    'Network security (App Transport Security)',
    x.atsArbitraryLoads
      ? f('ios.ats', 'warning', 'appStore', 'Insecure network loads allowed for every domain',
          'NSAllowsArbitraryLoads is on, so the app may load plain HTTP from any server. App Review can ask you to justify it, and it weakens user security.',
          'Turn it off and add NSExceptionDomains only for the servers that still need HTTP.')
      : x.atsInsecureDomains.length
        ? f('ios.ats.domains', 'info', 'appStore', `${x.atsInsecureDomains.length} domain${x.atsInsecureDomains.length > 1 ? 's' : ''} allowed over plain HTTP`,
            `${x.atsInsecureDomains.slice(0, 6).join(', ')}${x.atsInsecureDomains.length > 6 ? ' and more' : ''}. Test or internal hosts here are a common leftover in store builds.`,
            'Remove exceptions for test and internal servers before you submit.')
        : null,
  );

  r.check(
    'Export compliance answered in the build',
    x.exemptEncryptionKey === null
      ? f('ios.encryption', 'info', 'appStore', 'Export compliance not set',
          'ITSAppUsesNonExemptEncryption is missing, so App Store Connect asks the encryption question for every build before it can go to TestFlight or review.',
          'If the app only uses standard HTTPS and Apple system encryption, add ITSAppUsesNonExemptEncryption = NO to Info.plist.')
      : null,
  );

  if (meta.profileExpiresAt) {
    const days = Math.floor((Date.parse(meta.profileExpiresAt) - Date.now()) / 86_400_000);
    r.check(
      'Provisioning profile valid',
      days < 0
        ? f('ios.profile.expired', 'blocker', 'install', 'Provisioning profile expired',
            `The profile expired ${-days} day${-days === 1 ? '' : 's'} ago. Testers can no longer install this build.`,
            'Renew the profile in the Apple Developer portal, export the build again and upload it.')
        : days <= 14
          ? f('ios.profile.expiring', 'warning', 'install', `Provisioning profile expires in ${days} day${days === 1 ? '' : 's'}`,
              'After that date this build stops installing and opening on test devices.',
              'Renew the profile in the Apple Developer portal and upload a new build before it expires.')
          : null,
    );
  }
  if (meta.distribution === 'app-store') {
    r.check('Installable from a link', f('ios.profile.appstore', 'info', 'install', 'App Store distribution build',
      'This build is signed for App Store distribution. It is the right file for App Store Connect, but testers cannot install it from a link.',
      'For testers, export with Ad Hoc or Enterprise signing and register their devices with the UDID tool.'));
  }
}

// ---------------------------------------------------------------- Android

function android(r: Runner, b: ReadinessInput, x: AndroidFacts) {
  const meta = (b.meta ?? {}) as { targetSdk?: string | null; debuggable?: boolean; nativeCode?: string[] };
  const target = Number(meta.targetSdk);
  const need = PLAY_TARGET[x.formFactor] ?? 36;
  const kind = x.formFactor === 'phone' ? '' : ` for ${x.formFactor === 'tv' ? 'Android TV' : x.formFactor === 'wear' ? 'Wear OS' : 'Android Automotive'} apps`;

  r.check(
    `Target API ${need} or higher`,
    !Number.isFinite(target) || target < need
      ? f('android.target', 'blocker', 'play', `Targets API ${Number.isFinite(target) ? target : 'unknown'}, Play needs ${need}`,
          `Since August 31, 2026 new apps and updates on Google Play must target API ${need}${kind} or higher. You can ask Google for an extension to November 1, 2026.${target < 35 ? ' Existing apps below API 35 are also hidden from new users on newer Android versions.' : ''}`,
          `Set targetSdk to ${need} in build.gradle, test the behaviour changes of each Android version you skip, and build again.`)
      : null,
  );

  r.check(
    'Not a debuggable build',
    meta.debuggable || x.testOnly
      ? f('android.debuggable', 'blocker', 'play', meta.debuggable ? 'Debuggable build' : 'Test only build',
          `The manifest has ${meta.debuggable ? 'android:debuggable' : 'android:testOnly'} set. Google Play rejects these builds. This is fine for testers.`,
          'Build the release variant (for example ./gradlew bundleRelease) instead of the debug one.')
      : null,
  );

  if (x.debugCertificate !== null) {
    r.check(
      'Signed with a release key',
      x.debugCertificate
        ? f('android.debugcert', 'blocker', 'play', 'Signed with the debug key',
            'This build is signed with the Android debug certificate. Google Play rejects it, and testers would have to uninstall it before installing the Play version.',
            x.stack === 'flutter'
              ? 'New Flutter projects sign release builds with the debug key until you change it. Create an upload key, add a release entry under signingConfigs in android/app/build.gradle.kts (or build.gradle), set signingConfig to it in buildTypes release, build again with flutter build appbundle, and use Play App Signing.'
              : 'Create an upload key, add a signingConfig for the release build type, and use Play App Signing.')
        : null,
    );
  }

  const abis = meta.nativeCode ?? [];
  if (abis.length) {
    r.check(
      'Native code for phones (ARM)',
      !abis.some((a) => a.startsWith('arm'))
        ? f('android.abi.x86only', 'warning', 'install', `Only ${abis.join(', ')} native code`,
            `This build has native libraries for ${abis.join(', ')} only, which is what emulators and some Chromebooks run. Phones and tablets use ARM (arm64-v8a), so Android refuses to install it there ("App not installed").`,
            x.stack === 'flutter'
              ? 'Build without --target-platform android-x64 (flutter build apk builds every ABI by default), or pass --target-platform android-arm64,android-arm, then upload again.'
              : 'Add arm64-v8a (and armeabi-v7a for older phones) to abiFilters, or build the release variant for devices instead of the emulator, then upload again.')
        : null,
    );
  }
  r.check(
    '64-bit native code',
    (abis.includes('armeabi-v7a') && !abis.includes('arm64-v8a')) || (abis.includes('x86') && !abis.includes('x86_64'))
      ? f('android.64bit', 'blocker', 'play', 'Native code without a 64-bit version',
          `The app ships ${abis.join(', ')} libraries without the matching 64-bit ABI. Play requires 64-bit versions of all native code.`,
          'Add arm64-v8a (and x86_64 if you ship x86) to abiFilters, or update the SDK that brings these libraries.')
      : null,
  );

  const misaligned = x.libs16k.flatMap((l) => l.misaligned.map((m) => `${m} (${l.abi})`));
  if (x.libs16k.length) {
    r.check(
      '16 KB page size support',
      misaligned.length
        ? f('android.16k', Date.now() >= PLAY_16K_HARD ? 'blocker' : 'warning', 'play', `${misaligned.length} native ${misaligned.length > 1 ? 'libraries are' : 'library is'} not 16 KB aligned`,
            `${misaligned.slice(0, 8).join(', ')}${misaligned.length > 8 ? ' and more' : ''}. Play requires 16 KB page size support for apps that target Android 15 or higher, and from February 1, 2027 Play Console will not let you release updates without it. Phones with 16 KB pages may also refuse to run these libraries.`,
            'Update the SDKs these libraries come from, build your own native code with NDK r28 or later (or -Wl,-z,max-page-size=16384), and use AGP 8.5.1 or later so the APK is zip aligned for 16 KB.')
        : null,
    );
  }

  for (const d of DECLARED) {
    const hit = b.permissions.filter(d.perms);
    if (hit.length) {
      r.check(d.title, f(`android.perm.${d.title.toLowerCase().replace(/[^a-z]+/g, '-').replace(/^-|-$/g, '')}`, 'warning', 'play', `Needs a Play Console declaration: ${d.title}`,
        `${hit.join(', ')}. ${d.detail}`,
        'Remove the permission if the app can work without it. If it is core to the app, fill in the declaration under App content in Play Console before you submit.'));
    }
  }

  r.check(
    'Network security',
    x.cleartextTraffic && !x.networkSecurityConfig
      ? f('android.cleartext', 'info', 'play', 'Plain HTTP allowed for every server',
          'usesCleartextTraffic is on, so traffic can go unencrypted to any host. Play does not reject this, but it is a common security finding.',
          'Turn it off and add a network security config that allows HTTP only for the hosts that need it.')
      : null,
  );

  r.check('Upload format', f('android.aab', 'info', 'play', 'APK file',
    'This APK is right for testers. New apps on Google Play must be uploaded as an Android App Bundle (.aab).',
    'Build the bundle with ./gradlew bundleRelease when you submit to Play, and keep sharing APKs here for testing.'));
}

// ---------------------------------------------------------------- Expo

const listOf = (xs: string[], max = 6) => (xs.length > max ? `${xs.slice(0, max).join(', ')} and ${xs.length - max} more` : xs.join(', '));

/** Native libraries in `cur` that `prev` did not have (both lists non empty, else none). */
export function newNativeLibs(cur: ExpoFacts, prev: ExpoFacts): string[] {
  if (!cur.nativeLibs?.length || !prev.nativeLibs?.length) return [];
  const had = new Set(prev.nativeLibs);
  return cur.nativeLibs.filter((n) => !had.has(n));
}

function expo(r: Runner, b: ReadinessInput, x: ExpoFacts) {
  const meta = (b.meta ?? {}) as { distribution?: string };
  // Store builds (App Store signed) are meant to read the production channel; everything shared here as a test build is not.
  const testBuild = b.platform === 'ANDROID' || meta.distribution !== 'app-store';

  r.check(
    'Not a development client build',
    x.devClient
      ? f('expo.devclient', 'warning', 'install', 'Development build (expo-dev-client)',
          'This build includes the Expo development client. It opens the dev launcher and loads its JavaScript from a development server, so a tester who cannot reach your server sees an error or an empty launcher instead of the app.',
          'For testers, build with a profile that has no developmentClient (for example eas build --profile preview), or share this build only with developers who run npx expo start.')
      : null,
  );

  if (testBuild && x.updates !== false && x.channel) {
    r.check(
      'Test build reads a test update channel',
      x.channel.toLowerCase() === 'production'
        ? f('expo.channel.production', 'warning', 'install', 'Test build reads the production update channel',
            `expo-updates in this build asks for updates on the "${x.channel}" channel. Testers get what you publish for store users, and an update you publish to try on testers reaches store users too.`,
            'Give the test profile its own channel in eas.json (for example "channel": "preview"), build again, and publish test updates with eas update --channel preview.')
        : null,
    );
  }

  const prevFacts = (b.previous?.meta as { facts?: { expo?: ExpoFacts | null } } | null | undefined)?.facts?.expo;
  if (prevFacts && x.updates !== false && x.runtimeVersion && prevFacts.runtimeVersion) {
    const added = newNativeLibs(x, prevFacts);
    r.check(
      'Runtime version follows native changes',
      x.runtimeVersion !== prevFacts.runtimeVersion
        ? f('expo.runtime.changed', 'info', 'install', `Runtime version ${prevFacts.runtimeVersion} to ${x.runtimeVersion}`,
            `A native change since the previous build. Updates published for ${prevFacts.runtimeVersion} do not reach this build, and updates for ${x.runtimeVersion} do not reach the previous one.`,
            'Testers on the previous build need this build before they get updates made for it. Publish updates for this runtime after you share it.')
        : added.length
          ? f('expo.runtime.native', 'warning', 'install', `Native code changed, runtime version still ${x.runtimeVersion}`,
              `This build adds ${listOf(added)}. Updates are matched by runtime version only, so an update made for this build also reaches testers on the previous build, which does not have ${added.length === 1 ? 'this library' : 'these libraries'}, and can crash it.`,
              'Change runtimeVersion whenever native code changes (or use the fingerprint runtime version policy in app.json), then build again.')
          : null,
    );
  }
}

// ---------------------------------------------------------------- Flutter

function flutter(r: Runner, b: ReadinessInput, x: FlutterFacts) {
  if (!x.mode) return;
  const ios = b.platform === 'IOS';
  const cmd = ios ? 'flutter build ipa --release' : 'flutter build apk --release (or appbundle for Google Play)';
  r.check(
    'Flutter release build',
    x.mode === 'debug'
      ? f('flutter.mode.debug', ios ? 'blocker' : 'warning', 'install', 'Flutter debug build',
          ios
            ? 'This build runs Dart in debug mode (JIT, kernel_blob.bin). Since iOS 14 a Flutter debug build only opens from Xcode or the Flutter tool on a connected computer, so testers who tap the icon see it close at once. It is also much slower than what users get.'
            : 'This build runs Dart in debug mode (JIT, kernel_blob.bin): it starts and scrolls much slower than the release app, shows the debug banner and is far larger. Reports of "slow" or "janky" from testers often come from this.',
          `Build the release mode with ${cmd} and upload that file.`)
      : x.mode === 'profile'
        ? f('flutter.mode.profile', 'warning', 'install', 'Flutter profile build',
            `This is a profile build: AOT compiled, but with performance tracing and the Dart VM service on${ios ? '' : ', debuggable and signed like a debug build'}. It is meant for DevTools, not for testers, and does not behave exactly like the app users get.`,
            `Build the release mode with ${cmd} and upload that file.`)
        : null,
  );
}
